// ---------- Philadelphia guide data ----------
// Coordinates: either explicit [lat, lon] or a grid string "N/Street" (numbered street / named street),
// "W38/Walnut" for West Philly. Grid model calibrated on Isabella's own Apple Maps saves.

const HOME = { name: 'Home · 1310 Walnut St', ll: [39.9490, -75.1620] };
const WHARTON = { name: 'Huntsman Hall (Wharton)', ll: [39.9532, -75.1983] };

// named streets: latitude at Broad St
const NAMED = {
  Lehigh:39.992, Huntingdon:39.9907, Cumberland:39.9893, York:39.988, Dauphin:39.9866, Susquehanna:39.9853, Diamond:39.9839, Norris:39.9826, Berks:39.9812, Montgomery:39.9799, CecilB:39.9785, Oxford:39.9772, Jefferson:39.9758, Master:39.9745, Thompson:39.9731, Girard:39.9718, Poplar:39.9682, Brown:39.9668, Fairmount:39.9655, MtVernon:39.9645, Wallace:39.964, Green:39.9634, SpringGarden:39.9613, Hamilton:39.9605, Callowhill:39.9596, Noble:39.9588, Vine:39.958, Race:39.9565, Cherry:39.9558, Arch:39.9552, JFK:39.954, Market:39.9527, Ludlow:39.952, Ranstead:39.9518, Chestnut:39.9512, Drury:39.9507, Sansom:39.9502, Walnut:39.9492, Locust:39.9481, Latimer:39.9475, Spruce:39.9469, Delancey:39.9463, Pine:39.9456, Lombard:39.9445, South:39.9435, Bainbridge:39.9424, Fitzwater:39.9412, Catharine:39.94, Christian:39.9388, Carpenter:39.9376, Washington:39.9364, Ellsworth:39.935, Federal:39.9337, Wharton:39.9323, Reed:39.931, Dickinson:39.9297, Tasker:39.9284, Morris:39.9271, Moore:39.9258, Mifflin:39.9245, McKean:39.9232, Snyder:39.9219, Jackson:39.9206, Wolf:39.9193, Ritner:39.918, Porter:39.9167, Shunk:39.9154, Oregon:39.9141
};
function G(n, street){ // Center City / South / North grid (numbered street n, named street)
  const lat = NAMED[street] + (n-14)*0.000214;
  const lon = -75.1632 - (n-14)*0.00178 + 0.17*(lat-39.9526);
  return [lat, lon];
}
function W(n, street){ // West Philly grid (30th St sits on the west bank of the Schuylkill)
  const lat = NAMED[street] + (n-14)*0.000214;
  const lon = -75.1832 - (n-30)*0.0019 + 0.17*(lat-39.9526);
  return [lat, lon];
}
function P(s){ // resolve a point spec
  if (Array.isArray(s)) return s;
  const m = s.match(/^(W?)([\d.]+)\/(\w+)$/);
  return m[1] ? W(parseFloat(m[2]), m[3]) : G(parseFloat(m[2]), m[3]);
}

